Here's a simple Python program that can help you schedule fun family-friendly activities. This program will allow you to add, view, and delete activities.

```python
class FamilyActivityScheduler:
    def __init__(self):
        self.activities = {}

    def add_activity(self):
        activity_name = input("Enter the name of the activity: ")
        activity_date = input("Enter the date of the activity (YYYY-MM-DD): ")
        activity_time = input("Enter the time of the activity (HH:MM): ")
        activity_description = input("Enter a brief description of the activity: ")

        if activity_name not in self.activities:
            self.activities[activity_name] = {
                "date": activity_date,
                "time": activity_time,
                "description": activity_description
            }
            print(f"Activity '{activity_name}' added successfully.")
        else:
            print(f"Activity '{activity_name}' already exists.")

    def view_activities(self):
        if not self.activities:
            print("No activities scheduled.")
        else:
            print("Scheduled Activities:")
            for activity_name, activity in self.activities.items():
                print(f"Activity: {activity_name}")
                print(f"Date: {activity['date']}")
                print(f"Time: {activity['time']}")
                print(f"Description: {activity['description']}\n")

    def delete_activity(self):
        activity_name = input("Enter the name of the activity to delete: ")
        if activity_name in self.activities:
            del self.activities[activity_name]
            print(f"Activity '{activity_name}' deleted successfully.")
        else:
            print(f"Activity '{activity_name}' not found.")

    def run(self):
        while True:
            print("\nFamily Activity Scheduler")
            print("1. Add Activity")
            print("2. View Activities")
            print("3. Delete Activity")
            print("4. Quit")
            choice = input("Choose an option: ")

            if choice == "1":
                self.add_activity()
            elif choice == "2":
                self.view_activities()
            elif choice == "3":
                self.delete_activity()
            elif choice == "4":
                print("Goodbye!")
                break
            else:
                print("Invalid option. Please choose again.")

if __name__ == "__main__":
    scheduler = FamilyActivityScheduler()
    scheduler.run()
